import 'package:flutter/material.dart';

import '../../core/services/app_settings_service.dart';
import '../../core/services/notification_service.dart';
import '../../core/theme/app_colors.dart';
import '../../core/theme/app_dimens.dart';
import '../../shared/widgets/widgets.dart';

/// Persistent controls for every notification generated by the app.
class NotificationsScreen extends StatefulWidget {
  const NotificationsScreen({super.key});

  @override
  State<NotificationsScreen> createState() => _NotificationsScreenState();
}

class _NotificationsScreenState extends State<NotificationsScreen> {
  final AppSettingsService _settings = AppSettingsService.instance;
  bool _loading = true;
  bool _saving = false;

  @override
  void initState() {
    super.initState();
    _loadSettings();
  }

  Future<void> _loadSettings() async {
    try {
      await _settings.ensureNotificationSettingsLoaded();
    } catch (error) {
      debugPrint('Unable to load notification preferences: $error');
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  void _update(VoidCallback change) {
    _settings.setNotification(change);
  }

  Future<void> _setMasterNotifications(bool value) async {
    _update(() => _settings.masterNotifications = value);
    if (value) {
      try {
        await NotificationService.instance.requestPermissions();
      } catch (error) {
        debugPrint('Unable to request notification permission: $error');
      }
    }
  }

  Future<void> _save() async {
    if (_saving) return;
    setState(() => _saving = true);
    try {
      await _settings.saveNotificationSettings();
      if (!mounted) return;
      AppTopToast.show(
        context,
        message: 'Changes saved successfully',
        backgroundColor: Colors.green,
      );
      Navigator.of(context).pop();
    } catch (error) {
      if (!mounted) return;
      AppTopToast.show(
        context,
        message: 'Unable to save notification preferences',
        icon: Icons.error_outline_rounded,
      );
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Theme.of(context).scaffoldBackgroundColor,
      appBar: AppTopBar(
        title: 'Notifications',
        actions: [
          TextButton(
            onPressed: () {
              _settings.resetNotificationSettings();
              AppTopToast.show(
                context,
                message: 'Reset successfully',
                icon: Icons.refresh_rounded,
                backgroundColor: Colors.green,
              );
              Navigator.of(context).pop();
            },
            child: const Text(
              'Reset',
              style: TextStyle(
                color: Colors.red,
                fontWeight: FontWeight.w600,
              ),
            ),
          ),
        ],
      ),
      body: SafeArea(
        top: false,
        child: _loading
            ? const Center(child: CircularProgressIndicator())
            : ListenableBuilder(
                listenable: _settings,
                builder: (context, _) {
                  final enabled = _settings.masterNotifications;

                  return LayoutBuilder(
                    builder: (context, constraints) {
                      final horizontalPadding = constraints.maxWidth >= 600
                          ? 48.0
                          : AppSpacing.screenPadding;

                      return Column(
                        children: [
                          Expanded(
                            child: ListView(
                              padding: EdgeInsets.fromLTRB(
                                horizontalPadding,
                                AppSpacing.md,
                                horizontalPadding,
                                24,
                              ),
                              children: [
                                SettingsSectionCard(
                                  children: [
                                    ToggleSettingRow(
                                      title: 'Master Notifications',
                                      subtitle:
                                          'Turn all app notifications on or off',
                                      value: _settings.masterNotifications,
                                      onChanged: _setMasterNotifications,
                                    ),
                                    Padding(
                                      padding: EdgeInsets.symmetric(
                                        vertical: AppSpacing.sm,
                                      ),
                                      child: Divider(
                                        height: 1,
                                        color: AppColors.border,
                                      ),
                                    ),
                                    Opacity(
                                      opacity: enabled ? 1 : 0.4,
                                      child: IgnorePointer(
                                        ignoring: !enabled,
                                        child: Column(
                                          children: [
                                            ToggleSettingRow(
                                              title: 'Capture Saved',
                                              value:
                                                  _settings.notifyCaptureSaved,
                                              onChanged: (value) => _update(
                                                () => _settings
                                                        .notifyCaptureSaved =
                                                    value,
                                              ),
                                            ),
                                            ToggleSettingRow(
                                              title: 'Project Created',
                                              value:
                                                  _settings.notifyProjectCreated,
                                              onChanged: (value) => _update(
                                                () => _settings
                                                        .notifyProjectCreated =
                                                    value,
                                              ),
                                            ),
                                            ToggleSettingRow(
                                              title: 'GPS Accuracy Warning',
                                              value: _settings
                                                  .notifyGpsAccuracyWarning,
                                              onChanged: (value) => _update(
                                                () => _settings
                                                        .notifyGpsAccuracyWarning =
                                                    value,
                                              ),
                                            ),
                                            ToggleSettingRow(
                                              title: 'Storage Almost Full',
                                              value: _settings
                                                  .notifyStorageAlmostFull,
                                              onChanged: (value) => _update(
                                                () => _settings
                                                        .notifyStorageAlmostFull =
                                                    value,
                                              ),
                                            ),
                                            ToggleSettingRow(
                                              title:
                                                  'Location Services Disabled',
                                              value: _settings
                                                  .notifyLocationServicesDisabled,
                                              onChanged: (value) => _update(
                                                () => _settings
                                                        .notifyLocationServicesDisabled =
                                                    value,
                                              ),
                                            ),
                                            Padding(
                                              padding: EdgeInsets.symmetric(
                                                vertical: AppSpacing.sm,
                                              ),
                                              child: Divider(
                                                height: 1,
                                                color: AppColors.border,
                                              ),
                                            ),
                                            ToggleSettingRow(
                                              title: 'Sound',
                                              value:
                                                  _settings.notificationSound,
                                              onChanged: (value) => _update(
                                                () {
                                                  _settings.notificationSound =
                                                      value;
                                                  _settings
                                                          .notificationVibration =
                                                      !value;
                                                },
                                              ),
                                            ),
                                            ToggleSettingRow(
                                              title: 'Vibration',
                                              value: _settings
                                                  .notificationVibration,
                                              onChanged: (value) => _update(
                                                () {
                                                  _settings
                                                          .notificationVibration =
                                                      value;
                                                  _settings.notificationSound =
                                                      !value;
                                                },
                                              ),
                                            ),
                                          ],
                                        ),
                                      ),
                                    ),
                                  ],
                                ),
                              ],
                            ),
                          ),
                          const AdBannerWidget(),
                          Padding(
                            padding: EdgeInsets.fromLTRB(
                              horizontalPadding,
                              8,
                              horizontalPadding,
                              16,
                            ),
                            child: AppPrimaryButton(
                              label: _saving ? 'Saving...' : 'Save Changes',
                              icon: Icons.notifications_active_outlined,
                              onPressed: _saving ? null : _save,
                            ),
                          ),
                        ],
                      );
                    },
                  );
                },
              ),
      ),
    );
  }
}
